-- STAGING-ONLY baseline schema (never apply to production).
-- Source: exact sqlite_master DDL read (schema only, no rows) from production D1 thornie-dungeons-db on 2026-10-30,
-- which already includes the effects of migrations/auto 0012..0030. migrations/auto cannot build an empty DB because
-- base tables (players, characters, items, game_config, ...) pre-date the automated lane.
-- Staging bootstrap = this file, then INSERT the 0012..0030 names into d1_migrations (see staging QA workflow).
CREATE TABLE players (id TEXT PRIMARY KEY, password TEXT NOT NULL, created_at TEXT NOT NULL, diamonds INTEGER DEFAULT 0, active_slot INTEGER, password_hash TEXT, recovery_code_hash TEXT, auth_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE characters (   character_id TEXT PRIMARY KEY,   player_id TEXT NOT NULL,   slot_index INTEGER NOT NULL,   name TEXT DEFAULT '',   level INTEGER DEFAULT 1,   xp INTEGER DEFAULT 0,   stat_points INTEGER DEFAULT 0,   str INTEGER DEFAULT 0,   vit INTEGER DEFAULT 0,   agi INTEGER DEFAULT 0,   dex INTEGER DEFAULT 0,   luk INTEGER DEFAULT 0,   gold INTEGER DEFAULT 0,   unlocked_floor INTEGER DEFAULT 1,   potions INTEGER DEFAULT 2,   protection_stones INTEGER DEFAULT 0,   chest_pity INTEGER DEFAULT 0,   pets_json TEXT DEFAULT '[]',   active_pet_id TEXT DEFAULT '',   created_at TEXT,   updated_at TEXT , raid_stamina INTEGER NOT NULL DEFAULT 10, raid_stamina_updated_at TEXT NOT NULL DEFAULT '', pvp_tickets INTEGER NOT NULL DEFAULT 5, pvp_tickets_updated_at TEXT NOT NULL DEFAULT '', last_active_at TEXT NOT NULL DEFAULT '');
CREATE TABLE items (item_id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, slot_type TEXT NOT NULL DEFAULT '', equipped INTEGER NOT NULL DEFAULT 0, inventory_slot TEXT NOT NULL DEFAULT '', item_template_id TEXT NOT NULL DEFAULT '', rarity TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '', item_level INTEGER NOT NULL DEFAULT 0, enhance_level INTEGER NOT NULL DEFAULT 0, bound INTEGER NOT NULL DEFAULT 0, quantity INTEGER NOT NULL DEFAULT 1, atk INTEGER NOT NULL DEFAULT 0, def INTEGER NOT NULL DEFAULT 0, hp INTEGER NOT NULL DEFAULT 0, mp INTEGER NOT NULL DEFAULT 0, extra_json TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, character_id TEXT);
CREATE TABLE game_config (key TEXT PRIMARY KEY, value_json TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE admin_users (player_id TEXT PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'admin' CHECK (role IN ('owner', 'admin')), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE admin_sessions (session_id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES admin_users(player_id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, revoke_reason TEXT);
CREATE TABLE admin_audit_log (audit_id TEXT PRIMARY KEY, player_id TEXT REFERENCES players(id) ON DELETE SET NULL, event_type TEXT NOT NULL, target_type TEXT, target_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE auth_rate_limits (   rate_key TEXT PRIMARY KEY,   attempts INTEGER NOT NULL DEFAULT 0,   window_started_at TEXT NOT NULL,   blocked_until TEXT,   updated_at TEXT NOT NULL );
CREATE TABLE auth_sessions (   session_id TEXT PRIMARY KEY,   player_id TEXT NOT NULL,   token_hash TEXT NOT NULL UNIQUE,   created_at TEXT NOT NULL,   expires_at TEXT NOT NULL,   revoked_at TEXT,   revoke_reason TEXT,   remember_login INTEGER NOT NULL DEFAULT 0,   FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE );
CREATE TABLE character_run_state (character_id TEXT PRIMARY KEY, floor INTEGER NOT NULL DEFAULT 1, level INTEGER NOT NULL DEFAULT 1, xp INTEGER NOT NULL DEFAULT 0, hp INTEGER NOT NULL DEFAULT 0, mp INTEGER NOT NULL DEFAULT 0, base_atk INTEGER NOT NULL DEFAULT 0, base_def INTEGER NOT NULL DEFAULT 0, base_max_hp INTEGER NOT NULL DEFAULT 0, base_max_mp INTEGER NOT NULL DEFAULT 0, run_gold INTEGER NOT NULL DEFAULT 0, potions INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, pet_state_json TEXT NOT NULL DEFAULT '{}', FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE character_operation_receipts (character_id TEXT NOT NULL, operation TEXT NOT NULL, request_id TEXT NOT NULL, operation_token TEXT NOT NULL UNIQUE, payload_json TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (character_id, operation, request_id), FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE item_provenance (item_id TEXT PRIMARY KEY, original_player_id TEXT, original_character_id TEXT, origin_type TEXT NOT NULL DEFAULT 'unknown', origin_source_id TEXT, origin_context_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, acquired_at TEXT NOT NULL, tradeable INTEGER NOT NULL DEFAULT 0, bound INTEGER NOT NULL DEFAULT 0);
CREATE TABLE item_ownership_events (event_id TEXT PRIMARY KEY, item_id TEXT NOT NULL, from_player_id TEXT, from_character_id TEXT, to_player_id TEXT, to_character_id TEXT, event_type TEXT NOT NULL, context_json TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL);
CREATE TABLE battle_checkpoints (battle_id TEXT PRIMARY KEY, character_id TEXT NOT NULL, checkpoint_seq INTEGER NOT NULL DEFAULT 0, payload_json TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE battle_completions (battle_id TEXT PRIMARY KEY, character_id TEXT NOT NULL, result_json TEXT NOT NULL, completed_at TEXT NOT NULL, FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE character_settings (character_id TEXT PRIMARY KEY, quick_slots_json TEXT NOT NULL DEFAULT '[null,null,null,null]', updated_at TEXT NOT NULL, FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE character_shop_offers (character_id TEXT PRIMARY KEY, player_id TEXT NOT NULL, floor INTEGER NOT NULL, offers_json TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT, refresh_available_at TEXT, FOREIGN KEY(character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE character_blocks (blocker_character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, blocked_character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (blocker_character_id, blocked_character_id));
CREATE TABLE character_profile_frame_state (character_id TEXT PRIMARY KEY REFERENCES characters(character_id) ON DELETE CASCADE, equipped_frame_key TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE profile_frame_entitlements (entitlement_id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, frame_key TEXT NOT NULL, source_type TEXT NOT NULL DEFAULT '', source_key TEXT NOT NULL DEFAULT '', granted_at TEXT NOT NULL, expires_at TEXT, disabled_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (character_id, frame_key, source_type, source_key));
CREATE TABLE guilds (guild_id TEXT PRIMARY KEY, name TEXT NOT NULL, leader_character_id TEXT NOT NULL REFERENCES characters(character_id), created_at TEXT NOT NULL, normalized_name TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', join_policy TEXT NOT NULL DEFAULT 'open', level INTEGER NOT NULL DEFAULT 1, exp INTEGER NOT NULL DEFAULT 0);
CREATE TABLE guild_members (guild_id TEXT NOT NULL REFERENCES guilds(guild_id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'member', joined_at TEXT NOT NULL, contribution INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (guild_id, character_id));
CREATE TABLE guild_applications (application_id TEXT PRIMARY KEY, guild_id TEXT NOT NULL REFERENCES guilds(guild_id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE guild_donation_config (config_id INTEGER PRIMARY KEY CHECK (config_id = 1), whitelist_json TEXT NOT NULL CHECK (json_valid(whitelist_json)), guild_exp_per_item INTEGER NOT NULL CHECK (guild_exp_per_item >= 0), contribution_per_item INTEGER NOT NULL CHECK (contribution_per_item >= 0), min_quantity INTEGER NOT NULL, max_quantity INTEGER NOT NULL, level_cap INTEGER NOT NULL);
CREATE TABLE guild_donation_progression (level INTEGER PRIMARY KEY, cumulative_exp INTEGER NOT NULL UNIQUE CHECK (cumulative_exp >= 0));
CREATE TABLE guild_donation_stack_snapshot (donation_id TEXT NOT NULL, item_id TEXT NOT NULL, stack_position INTEGER NOT NULL, quantity INTEGER NOT NULL, PRIMARY KEY (donation_id, item_id));
CREATE TABLE guild_donations (donation_id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, character_id TEXT NOT NULL, junk_id TEXT NOT NULL, quantity INTEGER NOT NULL, guild_exp_granted INTEGER NOT NULL CHECK (guild_exp_granted >= 0), contribution_granted INTEGER NOT NULL CHECK (contribution_granted >= 0), guild_level_before INTEGER NOT NULL, guild_level_after INTEGER NOT NULL, guild_exp_before INTEGER NOT NULL, guild_exp_after INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, channel TEXT NOT NULL, guild_id TEXT REFERENCES guilds(guild_id) ON DELETE CASCADE, from_character_id TEXT NOT NULL REFERENCES characters(character_id), from_name TEXT NOT NULL DEFAULT '', to_character_id TEXT REFERENCES characters(character_id), message TEXT NOT NULL, created_at TEXT NOT NULL, conversation_key TEXT, client_nonce TEXT);
CREATE TABLE chat_read_state (character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, conversation_key TEXT NOT NULL, last_read_message_id INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY (character_id, conversation_key));
CREATE TABLE friend_requests (request_id TEXT PRIMARY KEY, sender_character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, receiver_character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, expires_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE friendships (character_id_a TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, character_id_b TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (character_id_a, character_id_b), CHECK (character_id_a < character_id_b));
CREATE TABLE daily_login_claim_receipts (character_id TEXT NOT NULL, claim_date TEXT NOT NULL, claim_token TEXT NOT NULL UNIQUE, reward_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (character_id, claim_date), FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE daily_login_claims (character_id TEXT PRIMARY KEY REFERENCES characters(character_id) ON DELETE CASCADE, login_streak INTEGER NOT NULL DEFAULT 0, last_claim_date TEXT NOT NULL DEFAULT '', total_claims INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE daily_login_rewards (day_index INTEGER PRIMARY KEY, reward_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE junk_info (junk_id TEXT PRIMARY KEY, name TEXT NOT NULL, icon TEXT NOT NULL DEFAULT '📦', created_at TEXT, updated_at TEXT);
CREATE TABLE leaderboard_history (date TEXT NOT NULL, character_id TEXT NOT NULL, player_id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', max_floor INTEGER NOT NULL DEFAULT 0, total_cp INTEGER NOT NULL DEFAULT 0, pet_cp INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, PRIMARY KEY (date, character_id));
CREATE TABLE leaderboard_stats (character_id TEXT PRIMARY KEY REFERENCES characters(character_id) ON DELETE CASCADE, player_id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', max_floor INTEGER NOT NULL DEFAULT 1, total_cp INTEGER NOT NULL DEFAULT 0, pet_cp INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE mailbox (mail_id TEXT PRIMARY KEY, character_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', gold INTEGER NOT NULL DEFAULT 0, diamonds INTEGER NOT NULL DEFAULT 0, junk_json TEXT NOT NULL DEFAULT '', claimed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, claimed_at TEXT NOT NULL DEFAULT '', items_json TEXT NOT NULL DEFAULT '', source_key TEXT NOT NULL DEFAULT '');
CREATE TABLE mailbox_claim_receipts (receipt_key TEXT PRIMARY KEY, character_id TEXT NOT NULL, mail_ids_json TEXT NOT NULL DEFAULT '[]', reward_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE monster_loot (entry_id TEXT PRIMARY KEY, monster_id TEXT NOT NULL, kind TEXT NOT NULL, item_type TEXT, rarity TEXT, junk_id TEXT, qty_min INTEGER DEFAULT 1, qty_max INTEGER DEFAULT 1, weight REAL DEFAULT 1, drop_chance REAL DEFAULT 1.0, created_at TEXT, updated_at TEXT);
CREATE TABLE pet_duplicates (player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, pet_def_id TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY (player_id, pet_def_id));
CREATE TABLE progress (player_id TEXT PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE, bank_gold INTEGER NOT NULL DEFAULT 0, diamonds INTEGER NOT NULL DEFAULT 0, best_floor INTEGER NOT NULL DEFAULT 1, potions INTEGER NOT NULL DEFAULT 2, char_level INTEGER NOT NULL DEFAULT 1, char_xp INTEGER NOT NULL DEFAULT 0, char_points INTEGER NOT NULL DEFAULT 0, char_str INTEGER NOT NULL DEFAULT 0, char_vit INTEGER NOT NULL DEFAULT 0, char_dex INTEGER NOT NULL DEFAULT 0, char_luk INTEGER NOT NULL DEFAULT 0, pets_json TEXT NOT NULL DEFAULT '[]', active_pet_id TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE raid_boss_state (raid_id TEXT PRIMARY KEY, date TEXT NOT NULL, boss_def_id TEXT NOT NULL DEFAULT '', boss_hp_max INTEGER NOT NULL DEFAULT 0, boss_hp_current INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, settled_at TEXT NOT NULL DEFAULT '');
CREATE TABLE raid_milestone_snapshots (raid_id TEXT NOT NULL, character_id TEXT NOT NULL, p99_json TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, PRIMARY KEY (raid_id, character_id), FOREIGN KEY (raid_id) REFERENCES raid_boss_state(raid_id) ON DELETE CASCADE, FOREIGN KEY (character_id) REFERENCES characters(character_id) ON DELETE CASCADE);
CREATE TABLE raid_participants (raid_id TEXT NOT NULL REFERENCES raid_boss_state(raid_id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, player_id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', total_damage INTEGER NOT NULL DEFAULT 0, last_hit_at TEXT NOT NULL, attempts_used INTEGER NOT NULL DEFAULT 0, total_contribution INTEGER NOT NULL DEFAULT 0, milestone_claimed TEXT NOT NULL DEFAULT '', PRIMARY KEY (raid_id, character_id));
CREATE TABLE raid_reward_claims (raid_id TEXT NOT NULL REFERENCES raid_boss_state(raid_id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, claimed_at TEXT NOT NULL, PRIMARY KEY (raid_id, character_id));
CREATE TABLE recipes (recipe_id TEXT PRIMARY KEY, result_item_def TEXT NOT NULL, materials_json TEXT NOT NULL DEFAULT '{}', source TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE run_state (player_id TEXT PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE, floor INTEGER NOT NULL DEFAULT 1, level INTEGER NOT NULL DEFAULT 1, xp INTEGER NOT NULL DEFAULT 0, hp INTEGER NOT NULL DEFAULT 0, mp INTEGER NOT NULL DEFAULT 0, base_atk INTEGER NOT NULL DEFAULT 0, base_def INTEGER NOT NULL DEFAULT 0, base_max_hp INTEGER NOT NULL DEFAULT 0, base_max_mp INTEGER NOT NULL DEFAULT 0, run_gold INTEGER NOT NULL DEFAULT 0, potions INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, character_id TEXT);
CREATE TABLE w6_legacy_item_cleanup_audit (item_id TEXT PRIMARY KEY, player_id TEXT, character_id TEXT, reason TEXT NOT NULL, slot_type TEXT, rarity TEXT, name TEXT, equipped INTEGER NOT NULL DEFAULT 0, inventory_slot TEXT, item_template_id TEXT, extra_json TEXT, deleted_at TEXT NOT NULL);
CREATE TABLE arena_seasons (season_id TEXT PRIMARY KEY, season_number INTEGER NOT NULL UNIQUE, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'finalizing', 'finalized')), finalized_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (ends_at > starts_at));
CREATE TABLE arena_character_state (character_id TEXT PRIMARY KEY REFERENCES characters(character_id) ON DELETE CASCADE, arena_coin INTEGER NOT NULL DEFAULT 0 CHECK (arena_coin >= 0), tickets INTEGER NOT NULL DEFAULT 0 CHECK (tickets >= 0 AND tickets <= 10), ticket_updated_at TEXT NOT NULL DEFAULT '', last_daily_ticket_date TEXT NOT NULL DEFAULT '', unlock_notice_seen INTEGER NOT NULL DEFAULT 0 CHECK (unlock_notice_seen IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE arena_matches (match_id TEXT PRIMARY KEY, season_id TEXT NOT NULL REFERENCES arena_seasons(season_id) ON DELETE CASCADE, attacker_character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, defender_type TEXT NOT NULL CHECK (defender_type IN ('player', 'bot')), defender_character_id TEXT REFERENCES characters(character_id) ON DELETE CASCADE, defender_bot_id TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'matchmaking' CHECK (source IN ('matchmaking', 'revenge')), reward_slot TEXT NOT NULL CHECK (reward_slot IN ('lower', 'equal', 'higher')), status TEXT NOT NULL DEFAULT 'prepared' CHECK (status IN ('prepared', 'active', 'done', 'expired')), seed INTEGER NOT NULL, snapshot_json TEXT NOT NULL, state_json TEXT NOT NULL DEFAULT '', result_json TEXT NOT NULL DEFAULT '', prepared_at TEXT NOT NULL, prepared_expires_at TEXT NOT NULL, activated_at TEXT NOT NULL DEFAULT '', ticket_consumed_at TEXT NOT NULL DEFAULT '', deadline_at TEXT NOT NULL DEFAULT '', completed_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK ((defender_type = 'player' AND defender_character_id IS NOT NULL AND defender_bot_id = '') OR (defender_type = 'bot' AND defender_character_id IS NULL AND defender_bot_id <> '')));
CREATE TABLE arena_idempotency_receipts (receipt_key TEXT PRIMARY KEY, kind TEXT NOT NULL, season_id TEXT REFERENCES arena_seasons(season_id) ON DELETE CASCADE, character_id TEXT REFERENCES characters(character_id) ON DELETE CASCADE, match_id TEXT REFERENCES arena_matches(match_id) ON DELETE CASCADE, payload_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE arena_match_actions (match_id TEXT NOT NULL REFERENCES arena_matches(match_id) ON DELETE CASCADE, action_key TEXT NOT NULL, action_seq INTEGER NOT NULL CHECK (action_seq >= 0), response_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (match_id, action_key), UNIQUE (match_id, action_seq));
CREATE TABLE arena_match_history (match_id TEXT PRIMARY KEY REFERENCES arena_matches(match_id) ON DELETE CASCADE, season_id TEXT NOT NULL REFERENCES arena_seasons(season_id) ON DELETE CASCADE, attacker_character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, defender_type TEXT NOT NULL CHECK (defender_type IN ('player', 'bot')), defender_character_id TEXT REFERENCES characters(character_id) ON DELETE CASCADE, defender_bot_id TEXT NOT NULL DEFAULT '', attacker_name TEXT NOT NULL DEFAULT '', defender_name TEXT NOT NULL DEFAULT '', attacker_result TEXT NOT NULL CHECK (attacker_result IN ('win', 'draw', 'loss')), attacker_rating_change INTEGER NOT NULL DEFAULT 0, defender_rating_change INTEGER NOT NULL DEFAULT 0, arena_coin_earned INTEGER NOT NULL DEFAULT 0 CHECK (arena_coin_earned >= 0), resolution TEXT NOT NULL DEFAULT 'normal' CHECK (resolution IN ('normal', 'surrender', 'timeout', 'cutoff')), completed_at TEXT NOT NULL, CHECK ((defender_type = 'player' AND defender_character_id IS NOT NULL AND defender_bot_id = '') OR (defender_type = 'bot' AND defender_character_id IS NULL AND defender_bot_id <> '')));
CREATE TABLE arena_opponent_state (season_id TEXT NOT NULL REFERENCES arena_seasons(season_id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, opponents_json TEXT NOT NULL DEFAULT '[]', refresh_available_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, PRIMARY KEY (season_id, character_id));
CREATE TABLE arena_pair_season_stats (season_id TEXT NOT NULL REFERENCES arena_seasons(season_id) ON DELETE CASCADE, character_id_a TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, character_id_b TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, encounter_count INTEGER NOT NULL DEFAULT 0 CHECK (encounter_count >= 0), updated_at TEXT NOT NULL, PRIMARY KEY (season_id, character_id_a, character_id_b), CHECK (character_id_a < character_id_b));
CREATE TABLE arena_season_players (season_id TEXT NOT NULL REFERENCES arena_seasons(season_id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(character_id) ON DELETE CASCADE, rating INTEGER NOT NULL DEFAULT 1000 CHECK (rating >= 1000), rating_reached_at TEXT NOT NULL, attack_wins INTEGER NOT NULL DEFAULT 0 CHECK (attack_wins >= 0), attack_draws INTEGER NOT NULL DEFAULT 0 CHECK (attack_draws >= 0), attack_losses INTEGER NOT NULL DEFAULT 0 CHECK (attack_losses >= 0), defense_wins INTEGER NOT NULL DEFAULT 0 CHECK (defense_wins >= 0), defense_draws INTEGER NOT NULL DEFAULT 0 CHECK (defense_draws >= 0), defense_losses INTEGER NOT NULL DEFAULT 0 CHECK (defense_losses >= 0), highest_rewarded_tier INTEGER NOT NULL DEFAULT 0 CHECK (highest_rewarded_tier BETWEEN 0 AND 3), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (season_id, character_id));
CREATE TABLE arena_setup (character_id TEXT PRIMARY KEY REFERENCES characters(character_id) ON DELETE CASCADE, pet_inst_id TEXT NOT NULL DEFAULT '', skill_slots_json TEXT NOT NULL DEFAULT '[null,null,null,null]', initialized_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_admin_audit_created ON admin_audit_log(created_at DESC);
CREATE INDEX idx_admin_audit_player ON admin_audit_log(player_id, created_at DESC);
CREATE UNIQUE INDEX idx_admin_sessions_one_active ON admin_sessions(player_id) WHERE revoked_at IS NULL;
CREATE INDEX idx_admin_sessions_player ON admin_sessions(player_id);
CREATE INDEX idx_admin_sessions_token_hash ON admin_sessions(token_hash);
CREATE INDEX idx_arena_history_attack ON arena_match_history(season_id, attacker_character_id, completed_at DESC);
CREATE INDEX idx_arena_history_defense ON arena_match_history(season_id, defender_character_id, completed_at DESC) WHERE defender_character_id IS NOT NULL;
CREATE INDEX idx_arena_matches_active_deadline ON arena_matches(deadline_at) WHERE status = 'active';
CREATE UNIQUE INDEX idx_arena_matches_open_attacker ON arena_matches(attacker_character_id) WHERE status IN ('prepared', 'active');
CREATE INDEX idx_arena_matches_prepared_expiry ON arena_matches(prepared_expires_at) WHERE status = 'prepared';
CREATE INDEX idx_arena_matches_season_attacker ON arena_matches(season_id, attacker_character_id, created_at DESC);
CREATE INDEX idx_arena_matches_season_defender ON arena_matches(season_id, defender_character_id, created_at DESC) WHERE defender_character_id IS NOT NULL;
CREATE INDEX idx_arena_pair_character_b ON arena_pair_season_stats(season_id, character_id_b);
CREATE INDEX idx_arena_receipts_character ON arena_idempotency_receipts(character_id, kind, created_at DESC);
CREATE INDEX idx_arena_receipts_season ON arena_idempotency_receipts(season_id, kind, created_at DESC);
CREATE INDEX idx_arena_season_players_character ON arena_season_players(character_id, season_id);
CREATE INDEX idx_arena_season_players_leaderboard ON arena_season_players(season_id, rating DESC, attack_wins DESC, rating_reached_at ASC);
CREATE INDEX idx_arena_season_players_pool ON arena_season_players(season_id, rating) WHERE (attack_wins + attack_draws + attack_losses) > 0;
CREATE INDEX idx_arena_seasons_ends_at ON arena_seasons(ends_at);
CREATE UNIQUE INDEX idx_arena_seasons_one_active ON arena_seasons(status) WHERE status = 'active';
CREATE INDEX idx_auth_rate_limits_updated ON auth_rate_limits(updated_at);
CREATE UNIQUE INDEX idx_auth_sessions_one_active ON auth_sessions(player_id) WHERE revoked_at IS NULL;
CREATE INDEX idx_auth_sessions_player ON auth_sessions(player_id);
CREATE INDEX idx_auth_sessions_token_hash ON auth_sessions(token_hash);
CREATE UNIQUE INDEX idx_battle_checkpoint_active_character ON battle_checkpoints(character_id) WHERE state = 'active';
CREATE INDEX idx_battle_checkpoint_character ON battle_checkpoints(character_id, updated_at);
CREATE INDEX idx_battle_completion_character ON battle_completions(character_id, completed_at);
CREATE INDEX idx_character_blocks_blocked ON character_blocks(blocked_character_id);
CREATE INDEX idx_character_operation_receipts_token ON character_operation_receipts(operation_token);
CREATE INDEX idx_characters_name_lower ON characters(LOWER(name));
CREATE UNIQUE INDEX idx_characters_player_slot ON characters(player_id, slot_index);
CREATE INDEX idx_chat_conversation ON chat_messages(conversation_key, created_at DESC);
CREATE INDEX idx_chat_guild ON chat_messages (guild_id, created_at DESC);
CREATE UNIQUE INDEX idx_chat_sender_nonce ON chat_messages(from_character_id, client_nonce) WHERE client_nonce IS NOT NULL;
CREATE INDEX idx_chat_whisper ON chat_messages (to_character_id, created_at DESC);
CREATE INDEX idx_chat_whisper_from ON chat_messages(from_character_id, created_at DESC);
CREATE INDEX idx_chat_world ON chat_messages (channel, created_at DESC);
CREATE INDEX idx_daily_login_claim_receipts_token ON daily_login_claim_receipts(claim_token);
CREATE UNIQUE INDEX idx_friend_requests_pending_pair ON friend_requests(sender_character_id, receiver_character_id) WHERE status = 'pending';
CREATE INDEX idx_friend_requests_receiver_status ON friend_requests(receiver_character_id, status);
CREATE INDEX idx_friend_requests_sender_status ON friend_requests(sender_character_id, status);
CREATE INDEX idx_friendships_b ON friendships(character_id_b);
CREATE INDEX idx_guild_app_character_status ON guild_applications(character_id, status);
CREATE INDEX idx_guild_app_guild_status ON guild_applications(guild_id, status, created_at DESC);
CREATE UNIQUE INDEX idx_guild_app_pending_pair ON guild_applications(guild_id, character_id) WHERE status = 'pending';
CREATE INDEX idx_guild_donations_character_created ON guild_donations(character_id, created_at DESC);
CREATE INDEX idx_guild_donations_guild_created ON guild_donations(guild_id, created_at DESC);
CREATE UNIQUE INDEX idx_guild_member_char ON guild_members (character_id);
CREATE UNIQUE INDEX idx_guild_name ON guilds (name);
CREATE UNIQUE INDEX idx_guilds_normalized_name ON guilds(normalized_name);
CREATE INDEX idx_item_ownership_events_item_time ON item_ownership_events(item_id, occurred_at);
CREATE INDEX idx_items_player ON items(player_id);
CREATE INDEX idx_items_player_slot ON items(player_id, slot_type);
CREATE INDEX idx_items_template ON items(player_id, item_template_id);
CREATE INDEX idx_lb_cp ON leaderboard_stats (total_cp DESC);
CREATE INDEX idx_lb_floor ON leaderboard_stats (max_floor DESC);
CREATE INDEX idx_lb_petcp ON leaderboard_stats (pet_cp DESC);
CREATE INDEX idx_leaderboard_history_date ON leaderboard_history(date);
CREATE INDEX idx_mailbox_char ON mailbox(character_id, claimed);
CREATE INDEX idx_mailbox_claim_receipts_character ON mailbox_claim_receipts(character_id, created_at DESC);
CREATE UNIQUE INDEX idx_mailbox_source_key ON mailbox(source_key) WHERE source_key <> '';
CREATE INDEX idx_monster_loot_monster ON monster_loot(monster_id);
CREATE UNIQUE INDEX idx_players_id_nocase ON players(LOWER(id));
CREATE INDEX idx_profile_frame_entitlement_lookup ON profile_frame_entitlements(character_id, frame_key, expires_at);
CREATE INDEX idx_raid_date ON raid_boss_state (date DESC);
CREATE INDEX idx_raid_dmg ON raid_participants (raid_id, total_damage DESC);
